  scrpt[33] = fstr(" BREMSSTRAHLUNG FROM CARBON ATOM                  ", 50)
  scrpt[34] = fstr(" BREMSSTRAHLUNG FROM HYDROGEN ATOM                ", 50)
  # CALCULATE POPULATION OF TORSIONAL STATES
  apop1 = exp(ein[1] / inpt.akt)
  apop2 = exp(2.0 * ein[1] / inpt.akt)
  apop3 = exp(3.0 * ein[1] / inpt.akt)
  apop4 = exp(4.0 * ein[1] / inpt.akt)
  apop5 = exp(5.0 * ein[1] / inpt.akt)
  apop6 = exp(6.0 * ein[1] / inpt.akt)
  apop7 = exp(7.0 * ein[1] / inpt.akt)
  apop8 = exp(8.0 * ein[1] / inpt.akt)
  apop9 = exp(9.0 * ein[1] / inpt.akt)
  apop10 = exp(10.0 * ein[1] / inpt.akt)
