  apop1 = apop1 / apopsum
  apop2 = apop2 / apopsum
  apop3 = apop3 / apopsum
  apop4 = apop4 / apopsum
  apop5 = apop5 / apopsum
  apop6 = apop6 / apopsum
  apop7 = apop7 / apopsum
  apop8 = apop8 / apopsum
  apop9 = apop9 / apopsum
  apop10 = apop10 / apopsum
