    if inpt.naniso == 0: peqel[2, i] = 0.5
    if inpt.naniso == 1: peqel[2, i] = pq1
    if inpt.naniso == 2: peqel[2, i] = pq2
    q[2, i] = qela
    if inpt.naniso == 0: q[2, i] = qmom
    # GROSS IONISATION
    qion[1, i] = 0.0
    peqion[1, i] = 0.5
