    # A1=(DLOG(Z1T(J))-DLOG(Z1T(J-1)))/(EBRM(J)-EBRM(J-1))
    # B1=(DLOG(Z1T(J))*EBRM(J-1)-DLOG(Z1T(J-1))*EBRM(J))/
    # /(EBRM(J-1)-EBRM(J))
    # QIN(25,I)=DEXP(A*EN+B)*4.0*1.D-24
    # QIN(26,I)=DEXP(A1*EN+B1)*10.0*1.D-24
    # 990 CONTINUE
    qsng = qin[12, i] + qin[13, i] + qin[14, i] + qin[15, i] + qin[16, i] + qin[17, i] + qin[18, i] + qin[19, i] + qin[20, i] + qin[21, i] + qin[22, i] + qin[23, i] + qin[24, i]
    qtrp = qin[10, i] + qin[11, i]
    qtotexc = qtrp + qsng
    q[1, i] = q[2, i] + q[5, i] + q[4, i] + qin[1, i] + qin[2, i] + qin[3, i] + qin[4, i] + qin[5, i] + qin[6, i] + qin[7, i] + qin[8, i] + qin[9, i] + qexctot
    # /QIN(5,I)+QIN(6,I)+QIN(7,I)+QIN(8,I)+QIN(9,I)+QEXCTOT+
    # /QIN(25,I)+QIN(26,I)
    # WRITE(6,991) EN,QTRP,QSNG,QTOTEXC
    # 991 FORMAT(' EN=',D12.4,' QTRP=',D12.4,' QSNG=',D12.4,' QEXCTOT=',
    # /D12.4)
    # WRITE(6,992) EN,QION(1,I),QION(2,I),QION(3,I)
    # 992 FORMAT(' EN=',D12.4,' ION1=',D12.4,' ION2=',D12.4,' ION3=',D12.4)
  block L998:
    # SAVE COMPUTE TIME
    fdo k, 14, nin:
      if inpt.efinal <= ein[k]:
        nin = k - 1
        break L998
  # IF(EFINAL.GT.1000.) NIN=NIN+2
  return
